<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\Http\Request; use Pterodactyl\Models\Server; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Facades\Activity; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\AutoAction\AutoActions; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class AutoActionController extends Controller { public function __construct(private AlertsMessageBag $alert) { } public function update(Request $request, Server $server): RedirectResponse { if (!AutoActions::enabled()) { throw new NotFoundHttpException(); } $data = $request->validate([ 'due_at' => ['nullable', 'string', 'max:40'], 'action' => ['nullable', 'string', 'max:32'], 'clear' => ['nullable', 'string'], ]); $back = redirect()->route('admin.servers.view.manage', $server->id); if (($data['clear'] ?? '') !== '' || trim((string) ($data['due_at'] ?? '')) === '') { if (AutoActions::forServer($server) !== null) { AutoActions::clear($server); Activity::event('server:auto-action.clear')->subject($server)->log(); } $this->alert->success('The auto action on this server has been removed.')->flash(); return $back; } $due = AutoActions::parseDue($data['due_at']); if ($due === null) { $this->alert->danger('That due date could not be read. Use the date field rather than typing it by hand.')->flash(); return $back; } $entry = AutoActions::set($server, $due, (string) ($data['action'] ?? ''), $request->user()?->id); Activity::event('server:auto-action.set') ->subject($server) ->property(['action' => $entry->action, 'due_at' => $entry->due_at?->toIso8601String()]) ->log(); $this->alert->success(AutoActions::describe($entry))->flash(); return $back; } } 